{"cards": [{"node_code": "N_aa2e2a71428290d7", "definition": "研究自卸汽车（翻斗车）的专用结构、举升机构、液压系统、卸料装置及适应重载工况的底盘设计与制造工艺。", "boundary": "本节点聚焦于具备自动卸货功能的特定车型。边界在于区分“自卸汽车”与“普通载货汽车”（无举升机构）、“自卸汽车”与“工程机械”（如挖掘机，侧重挖掘而非运输）。若内容涉及通用液压原理，归入汽车结构部件或通用工程；若涉及自卸车特有的举升角度、液压回路及货箱结构，归本节点。", "includes": ["自卸车举升机构、液压举升系统及控制装置", "自卸车货箱结构、加强筋设计及耐磨材料应用", "自卸车在矿山、建筑等重载工况下的底盘匹配与稳定性设计"], "excludes": ["普通平头或栏板载货汽车（无自卸功能）", "通用液压元件的基础理论（非自卸车专用）"], "sibling_distinctions": [{"other_code": "N_ebb10c299824c98a", "rule": "载货汽车侧重通用货物运输结构；自卸汽车侧重自动卸货机构及重载工况下的特殊结构。"}, {"other_code": "N_890fb99505fe14fe", "rule": "专用汽车侧重特定功能装置（如消防、医疗）；自卸汽车侧重运输过程中的卸货功能，若自卸车兼具其他专用功能，需视主要功能归属，纯自卸归本节点。"}], "cross_boundary_rule": "若内容涉及“自卸车液压系统与通用液压元件的对比”，主挂载自卸汽车；若仅讨论液压泵原理，归入通用汽车结构或机械类。"}, {"node_code": "N_2bdf7c54ac4d9237", "definition": "研究牵引车、挂车及汽车列车的结构原理、连接装置、动力学特性、匹配设计及运输组织技术。", "boundary": "本节点聚焦于“牵引-被牵引”组合运输系统。边界在于区分“牵引车/挂车”与“普通载货汽车”（一体式车身）、“汽车列车”与“单车运输”。若内容涉及牵引座、挂车轴、制动联动等专用技术，归本节点。若涉及挂车内部货物固定，归入载货汽车或物流包装。", "includes": ["牵引车（半挂牵引车、全挂牵引车）的结构设计与动力匹配", "挂车（半挂车、全挂车）的车架、悬挂、制动及连接装置", "汽车列车的动力学分析、操纵稳定性及运输效率优化"], "excludes": ["普通一体式载货汽车（无挂车连接）", "铁路机车与车厢的连接技术"], "sibling_distinctions": [{"other_code": "N_ebb10c299824c98a", "rule": "载货汽车通常指一体式货车；牵引车、挂车、汽车列车侧重分离式运输单元及其组合特性。"}, {"other_code": "N_aa2e2a71428290d7", "rule": "自卸汽车侧重卸货机构；牵引车/挂车侧重运输组合与连接技术，自卸半挂车若侧重挂车结构可归本节点，若侧重举升机构归自卸汽车。"}], "cross_boundary_rule": "若内容涉及“自卸半挂车的举升机构”，主挂载自卸汽车；若涉及“自卸半挂车的挂车轴与牵引座连接”，主挂载牵引车、挂车、汽车列车。"}, {"node_code": "N_890fb99505fe14fe", "definition": "研究在通用或专用底盘上安装特定功能装置，用于执行特殊任务（如消防、医疗、工程、环卫等）的汽车设计与技术。", "boundary": "本节点聚焦于“功能专用性”。边界在于区分“专用汽车”与“普通载货/客车”（无特殊功能装置）、“专用汽车”与“工程机械”（如起重机，若以运输为主归本节点，以作业为主归工程机械）。若内容涉及救护车担架、消防车水泵、油罐车罐体等专用装置，归本节点。", "includes": ["特种作业汽车（消防车、救护车、工程车、环卫车等）的功能装置设计", "专用汽车底盘改装技术、上装与底盘的匹配及稳定性", "专用汽车的安全标准、法规要求及特殊工况适应性"], "excludes": ["普通载货汽车（仅用于通用货物运输）", "纯工程机械（如挖掘机、装载机，无运输功能或运输非主要功能）"], "sibling_distinctions": [{"other_code": "N_aa2e2a71428290d7", "rule": "自卸汽车侧重卸货功能；专用汽车侧重其他特定功能（如消防、医疗），若自卸车兼具其他功能，需视主要功能，纯自卸归自卸汽车。"}, {"other_code": "N_ebb10c299824c98a", "rule": "载货汽车侧重通用运输；专用汽车侧重特定任务执行，如油罐车、冷藏车等。"}], "cross_boundary_rule": "若内容涉及“冷藏车制冷系统”，主挂载专用汽车；若涉及“冷藏车底盘结构”，主挂载载货汽车或汽车结构部件。"}]}
